const statusMap={"Corrigida":"corrected","Pendente":"pending","Em correção":"review","Com erro":"error"};
function statusClass(status){return "status-"+(statusMap[status]||"pending")}
function escapeHtml(value){return String(value||"").replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}
