function applyRepertoireFormat(field,format){const start=field.selectionStart,end=field.selectionEnd,value=field.value,selected=value.slice(start,end),token=format==="bold"?"**":"==";if(selected&&value.slice(start-token.length,start)===token&&value.slice(end,end+token.length)===token){field.setRangeText(selected,start-token.length,end+token.length,"select")}else if(selected){field.setRangeText(token+selected+token,start,end);field.setSelectionRange(start+token.length,start+token.length+selected.length)}else{field.setRangeText(token+token,start,end);field.setSelectionRange(start+token.length,start+token.length)}field.focus();updateRichEditor(field);field.dispatchEvent(new Event("input",{bubbles:true}))}
