function displayDate(value){if(!value)return "Agora";const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short",year:"numeric",timeZone:"America/Sao_Paulo"}).format(d).replace(" de "," de ")}
function allEssays(){return savedEssays}
function scoreValue(essay){return essay.result?essay.result.total_score:essay.score}
function competenciesHtml(essay){const result=essay.result;const values=result?result.competencies.map(function(c,i){return '<div class="competency"><span>'+escapeHtml(c.name||("C"+(i+1)))+'</span><strong>'+escapeHtml(c.score)+'</strong></div>'}).join(""):essay.competencies?essay.competencies.map(function(n,i){return '<div class="competency"><span>C'+(i+1)+'</span><strong>'+n+'</strong></div>'}).join(""):"";return values?'<div class="essay-divider"></div><div class="competencies">'+values+'</div>':""}
function renderComparedText(text,annotations,competencies){const source=String(text||"");const paragraphSpans=[];let searchFrom=0,number=0;source.split(/\n\s*\n/).forEach(function(part){if(!part.trim())return;number++;const start=source.indexOf(part,searchFrom);paragraphSpans.push({number:number,start:start,end:start+part.length,text:part});searchFrom=start+part.length});const ranges=[],usedQuotes={};(Array.isArray(annotations)?annotations:[]).forEach(function(item,index){const quote=String(item.quote||"");if(!quote)return;const paragraph=Number(item.paragraph)||1;const span=paragraphSpans.find(function(p){return p.number===paragraph})||paragraphSpans.find(function(p){return source.slice(p.start,p.end).includes(quote)});if(!span)return;const key=item.competence+"|"+span.number+"|"+quote;let from=usedQuotes[key]===undefined?span.start:usedQuotes[key],at=source.indexOf(quote,from);if(at<0||at+quote.length>span.end)at=source.indexOf(quote,span.start);if(at>=0&&at+quote.length<=span.end){usedQuotes[key]=at+quote.length;ranges.push({start:at,end:at+quote.length,name:String(item.competence||"").replace(/[^A-Za-z0-9]/g,""),id:"annotation-"+index})}});(competencies||[]).forEach(function(c){const name=String(c.name||"").replace(/[^A-Za-z0-9]/g,"");if(ranges.some(function(r){return r.name===name}))return;const quote=String(c.evidence||"").trim();if(quote.length<5)return;const at=source.toLocaleLowerCase("pt-BR").indexOf(quote.toLocaleLowerCase("pt-BR"));if(at>=0)ranges.push({start:at,end:at+quote.length,name:name,id:"criterion-"+name})});let html="",found=[];paragraphSpans.forEach(function(p){const relevant=ranges.filter(function(r){return r.start<p.end&&r.end>p.start});const boundaries=[p.start,p.end];relevant.forEach(function(r){boundaries.push(Math.max(p.start,r.start),Math.min(p.end,r.end))});boundaries.sort(function(a,b){return a-b});const unique=boundaries.filter(function(value,index,list){return index===0||value!==list[index-1]});html+='<p class="essay-paragraph"><span class="paragraph-number">'+p.number+'</span><span class="paragraph-text">';for(let i=0;i<unique.length-1;i++){const start=unique[i],end=unique[i+1];if(end<=start)continue;const covering=relevant.filter(function(r){return r.start<=start&&r.end>=end});const piece=escapeHtml(source.slice(start,end));if(!covering.length){html+=piece;continue}const ids=covering.map(function(r){return r.id});const names=covering.map(function(r){return r.name});covering.forEach(function(r){if(!found.includes(r.name))found.push(r.name)});html+='<mark id="'+ids[0]+'" data-annotation-ids="'+ids.join(' ')+'" class="evidence-mark '+names.map(function(name){return 'evidence-'+name}).join(' ')+'">'+piece+'</mark>'}html+='</span></p>'});return {html:html,found:found}}
function renderEssays(){const q=searchInput.value.trim().toLocaleLowerCase("pt-BR");const visible=allEssays().filter(function(e){return (currentFilter==="Todas"||e.status===currentFilter)&&(""+e.title+" "+e.theme).toLocaleLowerCase("pt-BR").includes(q)});list.classList.toggle("grid-view",currentView==="grid");list.innerHTML=visible.map(function(e){const score=scoreValue(e);const scoreLabel=e.type==="enem"?"NOTA ENEM":e.type==="argumentacao"?"SOMA OFICINA":"NOTA FINAL";const scoreHtml=score!==undefined&&score!==null?'<span>'+scoreLabel+'</span><strong>'+escapeHtml(score)+'</strong>':'<span>'+scoreLabel+'</span><strong>—</strong>';const mark=e.status==="Corrigida"?"✓":e.status==="Pendente"?"◷":e.status==="Em correção"?"◌":"!";const kind=e.type==="enem"?"Redação ENEM":e.type==="argumentacao"?"Oficina de argumentação":"";return '<article class="essay-card"><div class="essay-top"><div class="essay-main"><span class="status '+statusClass(e.status)+'">'+mark+' '+escapeHtml(e.status)+'</span><span class="essay-date">'+escapeHtml(e.createdAt?displayDate(e.createdAt):e.date)+'</span><h2>'+escapeHtml(e.title)+'</h2><p class="essay-theme"><span>♧</span>'+escapeHtml(e.theme)+(kind?' <span class="essay-kind">· '+kind+'</span>':"")+'</p>'+(e.status==="Com erro"&&e.error?'<p class="essay-error">'+escapeHtml(e.error)+'</p>':"")+'</div><div class="essay-score">'+scoreHtml+'</div></div>'+competenciesHtml(e)+'<div class="essay-card-actions">'+(e.status==="Corrigida"?'<button class="small-action" data-action="open" data-id="'+e.id+'">Ver correção →</button>':e.status==="Em correção"?'<span class="waiting-label">A IA está analisando sua redação…</span>':e.status==="Com erro"?'<button class="small-action" data-action="retry" data-id="'+e.id+'">Tentar novamente</button>':"")+(String(e.id).startsWith("demo-")?'':'<button class="small-action" data-action="delete" data-id="'+e.id+'">Excluir</button>')+'</div></article>'}).join("");empty.classList.toggle("hidden",visible.length>0);list.style.display=visible.length?"grid":"none"}
function showToast(message){toast.textContent=message;toast.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(function(){toast.classList.remove("show")},3500)}
function navigate(page){document.querySelectorAll(".page").forEach(function(p){p.classList.remove("active-page")});const target=document.querySelector("#"+page+"Page");if(target)target.classList.add("active-page");document.body.classList.toggle("correction-mode",page==="correction");document.querySelectorAll(".nav-item").forEach(function(b){b.classList.toggle("active",b.dataset.page===(page==="correction"?"essays":page))});document.querySelector("#sidebar").classList.remove("open");window.scrollTo({top:0,behavior:"smooth"});if(page==="correction"){const scoreCard=document.querySelector(".result-score"),screenButton=document.querySelector("#fullscreenCorrection");if(scoreCard&&screenButton)scoreCard.appendChild(screenButton)}if(page==="essays")renderEssays();if(page==="themes")renderThemes();if(page==="dashboard")renderDashboard();if(page==="repertoire")renderRepertoire()}
async function refreshEssays(){try{const response=await fetch("/api/essays");if(!response.ok)throw new Error();savedEssays=await response.json();renderEssays();renderDashboard()}catch(error){showToast("Não foi possível carregar as redações salvas.")}}
function startPolling(){if(savedEssays.some(function(e){return e.status==="Em correção"}))setTimeout(async function(){await refreshEssays();startPolling()},5000)}
function renderDashboard(){const corrected=savedEssays.filter(function(e){return e.status==="Corrigida"});document.querySelector("#dashboardSent").textContent=savedEssays.length;document.querySelector("#dashboardCorrected").textContent=corrected.length;document.querySelector("#dashboardThemes").textContent=savedThemes.length;document.querySelector("#dashboardCompletion").textContent=(savedEssays.length?Math.round(corrected.length/savedEssays.length*100):0)+"%";const recent=document.querySelector("#dashboardRecent");if(!recent)return;if(!savedEssays.length){recent.innerHTML='<p class="empty-inline">Nenhuma redação enviada ainda.</p>';return}recent.innerHTML=savedEssays.slice(0,5).map(function(essay){return '<div class="recent-row"><span class="status '+statusClass(essay.status)+'">'+escapeHtml(essay.status)+'</span><strong>'+escapeHtml(essay.title||"Sem título")+'</strong><span class="recent-date">'+escapeHtml(displayDate(essay.createdAt))+'</span><strong class="recent-score">'+(scoreValue(essay)!==undefined?escapeHtml(scoreValue(essay)):"—")+'</strong></div>'}).join("")}
function imagesForMotivator(theme,item,index){let images=Array.isArray(item.imagens)?item.imagens:item.imagem?[item.imagem]:[];if(!images.length&&index===0&&Array.isArray(theme.imagens))images=theme.imagens;return images}
function motivatorImagesMarkup(images){return images.length?'<div class="motivator-images">'+images.map(function(image){return '<figure><img src="'+escapeHtml(image.url)+'" alt="'+escapeHtml(image.alt||image.arquivo||"Imagem motivadora")+'" loading="lazy"><figcaption>'+escapeHtml(image.alt||image.arquivo||"Imagem do texto motivador")+'</figcaption></figure>'}).join("")+'</div>':''}
function renderThemes(){const list=document.querySelector("#themeList"),empty=document.querySelector("#emptyThemes");if(!list||!empty)return;list.innerHTML=savedThemes.map(function(theme){const motivators=Array.isArray(theme.textos_motivadores)?theme.textos_motivadores:[];const imageCount=motivators.reduce(function(total,item,index){return total+imagesForMotivator(theme,item,index).length},0);return '<article class="theme-card"><div class="theme-card-head"><span class="theme-axis">'+escapeHtml(theme.eixo)+'</span><span class="theme-count">'+motivators.length+' textos · '+imageCount+' imagens</span></div><h2>'+escapeHtml(theme.tema)+'</h2><details class="theme-details"><summary>Ver textos motivadores</summary><div class="theme-motivators">'+motivators.map(function(item,index){return '<article class="motivator-card"><h3>'+escapeHtml(item.titulo||("Texto motivador "+(index+1)))+'</h3>'+(item.fonte?'<p class="motivator-source">Fonte: '+escapeHtml(item.fonte)+'</p>':'')+'<p>'+escapeHtml(item.texto)+'</p>'+motivatorImagesMarkup(imagesForMotivator(theme,item,index))+'</article>'}).join("")+'</div></details><div class="theme-card-actions"><button class="button button-primary" data-use-theme="'+escapeHtml(theme.id)+'">Usar este tema</button></div></article>'}).join("");empty.classList.toggle("hidden",savedThemes.length>0);list.classList.toggle("hidden",savedThemes.length===0)}
async function refreshThemes(){try{const response=await fetch("/api/themes");if(!response.ok)throw new Error();savedThemes=await response.json();renderThemes();renderDashboard()}catch(error){showToast("Não foi possível carregar os temas salvos.")}}
function readFileAsBase64(file){return new Promise(function(resolve,reject){const reader=new FileReader();reader.onload=function(){resolve(String(reader.result).split(",").pop())};reader.onerror=reject;reader.readAsDataURL(file)})}
async function importThemeFiles(){const input=document.querySelector("#themeFiles"),button=document.querySelector("#importThemeButton"),files=Array.from(input.files||[]);if(!files.length)return;const jsonFiles=files.filter(function(file){return file.name.toLowerCase().endsWith(".json")});if(jsonFiles.length!==1){showToast("Selecione exatamente um arquivo JSON e as imagens dele.");input.value="";return}const imageFiles=files.filter(function(file){return file!==jsonFiles[0]});if(imageFiles.length>8){showToast("Cada tema pode ter até 8 imagens.");input.value="";return}button.disabled=true;button.textContent="Importando…";try{const theme=JSON.parse((await jsonFiles[0].text()).replace(/^\uFEFF/,""));const images=await Promise.all(imageFiles.map(async function(file){return {filename:file.name,mime:file.type,dataBase64:await readFileAsBase64(file)}}));const response=await fetch("/api/themes/import",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({theme:theme,images:images})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível importar o tema.");savedThemes.unshift(data);renderThemes();renderDashboard();showToast("Tema salvo em data/themes.")}catch(error){showToast(error.message||"Verifique o JSON e tente novamente.")}finally{input.value="";button.disabled=false;button.innerHTML="＋ Importar tema"}}
function useTheme(themeId){const theme=savedThemes.find(function(item){return item.id===themeId});if(!theme)return;selectedTheme=theme;document.querySelector("#essayTheme").value=theme.tema;document.querySelector("#essayType").value="enem";document.querySelector("#modeHint").textContent="Tema carregado de “"+theme.eixo+"”. A IA avaliará as cinco competências do ENEM.";const preview=document.querySelector("#selectedThemeContext"),texts=Array.isArray(theme.textos_motivadores)?theme.textos_motivadores:[];const colors=[{name:"Amarelo",value:"#fff09a"},{name:"Verde",value:"#b9efc9"},{name:"Azul",value:"#b9ddff"},{name:"Rosa",value:"#ffc6d5"}];preview.innerHTML='<div class="motivator-panel-heading"><strong>Textos motivadores deste tema</strong><button type="button" class="text-button" id="toggleMotivators">Minimizar textos</button></div>'+(texts.length?texts.map(function(item,index){const images=imagesForMotivator(theme,item,index);return '<details class="motivator-entry" open><summary>'+escapeHtml(item.titulo||("Texto motivador "+(index+1)))+'</summary><div class="motivator-toolbar" role="toolbar" aria-label="Marca-texto">'+colors.map(function(color){return '<button type="button" class="marker-swatch" data-marker-color="'+color.value+'" style="--marker-color:'+color.value+'" aria-label="Marca-texto '+color.name+'" title="Marca-texto '+color.name+'"></button>'}).join("")+'<span>Selecione um trecho e escolha uma cor</span></div><div class="motivator-copy">'+escapeHtml(item.texto)+'</div>'+motivatorImagesMarkup(images)+(item.fonte?'<small>Fonte: '+escapeHtml(item.fonte)+'</small>':'')+'</details>'}).join(""):'<p>Este tema não tem textos motivadores cadastrados.</p>');preview.classList.remove("hidden");navigate("new");showToast("Tema e textos motivadores carregados.")}
function applyMotivatorHighlight(button){const selection=window.getSelection(),copy=button.closest(".motivator-entry").querySelector(".motivator-copy");if(!selection||selection.rangeCount===0||selection.isCollapsed){showToast("Selecione um trecho do texto motivador primeiro.");return}const range=selection.getRangeAt(0);if(!copy.contains(range.startContainer)||!copy.contains(range.endContainer)){showToast("Selecione o trecho dentro do mesmo texto motivador.");return}const mark=document.createElement("mark");mark.style.setProperty("--mark-color",button.dataset.markerColor);try{mark.appendChild(range.extractContents());range.insertNode(mark);selection.removeAllRanges()}catch(error){showToast("Não foi possível marcar esse trecho. Tente selecionar palavras completas.")}}
function toggleMotivators(){const preview=document.querySelector("#selectedThemeContext"),entries=Array.from(preview.querySelectorAll(".motivator-entry")),shouldOpen=entries.some(function(item){return !item.open});entries.forEach(function(item){item.open=shouldOpen});const button=document.querySelector("#toggleMotivators");if(button)button.textContent=shouldOpen?"Minimizar textos":"Expandir textos"}
document.addEventListener("click",function(event){const marker=event.target.closest("[data-marker-color]");if(marker){applyMotivatorHighlight(marker);return}if(event.target.closest("#toggleMotivators"))toggleMotivators()});
document.addEventListener("mousedown",function(event){if(event.target.closest(".marker-swatch"))event.preventDefault()});
document.querySelector("#essayText").addEventListener("keydown",function(event){if(event.key!=="Tab")return;event.preventDefault();const field=event.currentTarget,value=field.value,start=field.selectionStart,end=field.selectionEnd;let from=start,to=end,inserted;if(event.shiftKey){from=value.lastIndexOf("\n",Math.max(0,start-1))+1;const linePrefix=value.slice(from,start),spaces=linePrefix.match(/^ {1,4}/);if(!spaces)return;inserted=value.slice(start,end);field.value=value.slice(0,from)+linePrefix.slice(spaces[0].length)+inserted+value.slice(end);const offset=spaces[0].length;field.setSelectionRange(Math.max(from,start-offset),Math.max(from,end-offset));return}if(start!==end&&value.slice(start,end).includes("\n")){from=value.lastIndexOf("\n",Math.max(0,start-1))+1;to=end;const block=value.slice(from,to).split("\n").map(function(line){return "    "+line}).join("\n");field.value=value.slice(0,from)+block+value.slice(to);field.setSelectionRange(start+4,end+4*block.split("\n").length);return}inserted="    ";field.value=value.slice(0,start)+inserted+value.slice(end);field.setSelectionRange(start+inserted.length,start+inserted.length)});

function openResult(essay,restore){const content=document.querySelector("#resultContent");const result=essay.result||{};const score=scoreValue(essay);const workshop=essay.type==="argumentacao";const competencies=result.competencies||[];const annotations=Array.isArray(result.annotations)?result.annotations:[];const c5Elements=Array.isArray(result.competency5_elements)?result.competency5_elements:[];const c5Highlights=c5Elements.filter(function(element){return element.present&&element.evidence}).map(function(element){return {competence:"C5",paragraph:element.paragraph,quote:element.evidence}});const compared=renderComparedText(essay.text,annotations.concat(c5Highlights),competencies);document.querySelector("#resultTitle").textContent=essay.title||"Sem título";document.querySelector("#resultTheme").textContent=(essay.theme||"")+(workshop?" · Oficina de argumentação":" · Redação ENEM");document.querySelector("#resultDate").textContent=displayDate(essay.createdAt||essay.date);const legend=competencies.map(function(c){const code=String(c.name||"").replace(/[^A-Za-z0-9]/g,"");return '<span class="evidence-legend-item"><i class="evidence-dot evidence-'+code+'"></i>'+escapeHtml(c.name)+'</span>'}).join("");const scoreLabel=workshop?"Soma de C1, C3 e C4":"Nota estimada";const competencyTitles={C1:"Domínio da modalidade escrita formal",C2:"Compreensão do tema e repertório",C3:"Seleção e organização dos argumentos",C4:"Coesão e mecanismos linguísticos",C5:"Proposta de intervenção"};function renderAnnotationCard(a,index){const code=String(a.competence||"");return '<article class="annotation-card"><div class="annotation-meta"><span class="annotation-tag evidence-'+escapeHtml(code)+'">'+escapeHtml(code)+'</span><span>Parágrafo '+escapeHtml(a.paragraph||"—")+'</span></div><blockquote>“'+escapeHtml(a.quote)+'”</blockquote><h4>'+escapeHtml(a.issue||"Ponto de atenção")+'</h4><div class="annotation-explanation"><strong>Por que revisar</strong><p>'+escapeHtml(a.comment||"")+'</p></div>'+(a.correction?'<div class="annotation-correction"><strong>Forma corrigida</strong><p>'+escapeHtml(a.correction)+'</p></div>':'')+(a.suggestion?'<div class="suggestion"><strong>Sugestão</strong><p>'+escapeHtml(a.suggestion)+'</p></div>':'')+(a.tip?'<div class="annotation-tip"><strong>Dica</strong><p>'+escapeHtml(a.tip)+'</p></div>':'')+'<button class="text-button evidence-jump" data-evidence-id="annotation-'+index+'">Ver trecho no texto ↗</button></article>'}
const c1AnnotationCards=annotations.map(function(a,index){return {a:a,index:index}}).filter(function(item){return String(item.a.competence).toUpperCase()==="C1"}).map(function(item){return renderAnnotationCard(item.a,item.index)}).join("");
const criteria=competencies.map(function(c){const code=String(c.name||"").replace(/[^A-Za-z0-9]/g,"");const related=annotations.map(function(a,index){return {a:a,index:index}}).filter(function(x){return x.a.competence===code});const evidence=String(c.evidence||"");const jump=related.length?related.map(function(x){return '<button class="text-button evidence-jump" data-evidence-id="annotation-'+x.index+'">Localizar apontamento no texto ↗</button>'}).join(""):evidence&&compared.found.includes(code)?'<button class="text-button evidence-jump" data-evidence-id="criterion-'+code+'">Localizar no texto ↗</button>':'<span class="no-evidence">Sem trecho específico destacado.</span>';const c5Checklist=code==="C5"?(Array.isArray(result.competency5_elements)?'<div class="c5-checklist"><strong>Checklist quantitativo da proposta</strong><p>Começa em 200 pontos. Cada elemento ausente desconta 40; cada presente conta 40.</p><ul>'+c5Elements.map(function(element,index){const markIndex=annotations.length+index;return '<li class="'+(element.present?"c5-present":"c5-missing")+'"><div class="c5-element-line"><span>'+escapeHtml(element.label)+'</span><b>'+(element.present?"Presente · +40":"Ausente · −40")+'</b></div>'+(element.present?'<blockquote>“'+escapeHtml(element.evidence)+'”</blockquote><button class="text-button evidence-jump" data-evidence-id="annotation-'+markIndex+'">Localizar evidência no texto ↗</button>':'<small>Este elemento foi descontado da pontuação.</small>')+'</li>'}).join("")+'</ul><small>A contagem segue a regra personalizada deste app e não substitui a avaliação oficial do Inep.</small></div>':'<p class="no-evidence">O checklist quantitativo não foi salvo nesta correção anterior.</p>'):"";return '<details class="comparison-criterion competency-tab"'+(code==="C1"?' open':'')+'><summary><span class="competency-tab-name">'+escapeHtml(c.name)+'<small>'+escapeHtml(competencyTitles[code]||"")+'</small></span><span class="competency-tab-score">'+escapeHtml(c.score)+' <small>/ 200</small></span><span class="competency-tab-chevron" aria-hidden="true">⌄</span></summary><div class="competency-tab-content"><p>'+escapeHtml(c.feedback)+'</p>'+(Array.isArray(c.tips)&&c.tips.length?'<div class="competency-tips"><strong>Dicas práticas</strong><ul>'+c.tips.map(function(tip){return '<li>'+escapeHtml(tip)+'</li>'}).join("")+'</ul></div>':'')+c5Checklist+(code==="C1"?'<section class="c1-deep-dive"><h4>Aprofundamento de C1 · '+annotations.filter(function(a){return String(a.competence).toUpperCase()==="C1"}).length+' apontamentos</h4>'+(c1AnnotationCards?'<div class="annotation-list">'+c1AnnotationCards+'</div>':'<p class="no-evidence">Nenhum desvio específico foi anotado nesta competência.</p>')+'</section>':'')+jump+'</div></details>'}).join("");const annotationCards=annotations.map(function(a,index){return {a:a,index:index}}).filter(function(item){return String(item.a.competence).toUpperCase()!=="C1"}).map(function(item){return renderAnnotationCard(item.a,item.index)}).join("");const extra=[];if(Array.isArray(result.repetitions)&&result.repetitions.length)extra.push('<section class="detail-panel"><h3>Repetições e alternativas</h3>'+result.repetitions.map(function(x){return '<p><strong>'+escapeHtml(x.word)+'</strong> · '+escapeHtml(x.count)+' ocorrências'+(x.alternatives&&x.alternatives.length?' — alternativas: '+x.alternatives.map(escapeHtml).join(', '):'')+'</p>'}).join("")+'</section>');const connectors=result.connector_analysis;if(connectors){extra.push('<section class="detail-panel"><h3>Coesão identificada</h3><p><strong>'+escapeHtml(connectors.count||0)+'</strong> conectivos identificados</p>'+((connectors.items||[]).length?'<ul>'+connectors.items.map(function(x){return '<li><strong>'+escapeHtml(x.term)+'</strong> ('+escapeHtml(x.count)+'): '+escapeHtml(x.function)+'</li>'}).join("")+'</ul>':'')+((connectors.reference_resources||[]).length?'<p>Referências: '+connectors.reference_resources.map(escapeHtml).join(' · ')+'</p>':'')+'</section>')};content.innerHTML='<div class="result-layout"><section class="comparison-column original-column"><div class="comparison-heading"><div><h3>Texto enviado</h3><p>Parágrafos numerados e trechos ligados aos comentários</p></div><span>'+String(essay.text||"").trim().split(/\s+/).filter(Boolean).length+' palavras</span></div><div class="evidence-legend">'+legend+'</div><article class="essay-original" id="essayOriginal">'+(compared.html||'<p class="no-evidence">O texto original não está disponível nesta correção.</p>')+'</article></section><section class="comparison-column feedback-column"><div class="result-score"><strong>'+escapeHtml(score===undefined?"—":score)+'</strong><span> / '+(workshop?"600":"1000")+'</span><small>'+scoreLabel+(workshop?" · indicador pedagógico, não nota ENEM":" · escala ENEM")+'</small></div>'+(result.summary?'<p class="result-summary">'+escapeHtml(result.summary)+'</p>':'')+'<h3>Competências avaliadas</h3><div class="result-competencies">'+criteria+'</div>'+(result.annotations?'<p class="c1-coverage">C1: '+annotations.filter(function(a){return a.competence==="C1"}).length+' desvios destacados no texto</p>':'')+(annotationCards?'<h3>Apontamentos por competência</h3>'+ '<div class="annotation-list">'+annotationCards+'</div>':'<p class="no-evidence">Esta correção não possui apontamentos detalhados por trecho.</p>')+extra.join("")+((result.strengths||[]).length?'<h3>Pontos fortes</h3><ul>'+result.strengths.map(function(x){return '<li>'+escapeHtml(x)+'</li>'}).join("")+'</ul>':'')+((result.improvements||[]).length?'<h3>Próximos passos</h3><ul>'+result.improvements.map(function(x){return '<li>'+escapeHtml(x)+'</li>'}).join("")+'</ul>':'')+'<p class="result-disclaimer">Retorno gerado por IA para fins de estudo. Use como apoio e confira os critérios com seu professor.</p></section></div>';navigate("correction");if(!restore)history.pushState({page:"correction",essayId:essay.id},"","#correcao/"+encodeURIComponent(essay.id))}
async function submitEssay(){const button=document.querySelector("#submitEssay"),type=document.querySelector("#essayType").value,theme=document.querySelector("#essayTheme").value.trim(),text=document.querySelector("#essayText").value.trim(),title=document.querySelector("#essayTitle").value.trim()||"Sem título";if(!type){showToast("Escolha Redação ENEM ou Oficina de argumentação.");document.querySelector("#essayType").focus();return}if(!theme||!text){showToast("Preencha o tema e o texto da redação para continuar.");return}button.disabled=true;button.textContent="Enviando…";try{const response=await fetch("/api/essays",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:title,theme:theme,text:text,type:type,promptContext:selectedTheme&&selectedTheme.tema===theme?JSON.stringify(selectedTheme.textos_motivadores||[]):""})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível enviar a redação.");savedEssays.unshift(data);document.querySelector("#essayTitle").value="";document.querySelector("#essayTheme").value="";selectedTheme=null;document.querySelector("#selectedThemeContext").classList.add("hidden");document.querySelector("#selectedThemeContext").innerHTML="";document.querySelector("#essayText").value="";document.querySelector("#essayType").value="";document.querySelector("#wordCount").textContent="0 palavras";document.querySelector("#modeHint").textContent="A atividade define os critérios usados pela IA na correção.";currentFilter="Todas";document.querySelectorAll(".filter").forEach(function(b){b.classList.toggle("active",b.dataset.filter==="Todas")});navigate("essays");showToast("Redação enviada. Ela aparecerá aqui enquanto a IA faz a correção.");startPolling()}catch(error){showToast(error.message||"Falha ao enviar. Confira se o servidor está ligado.")}finally{button.disabled=false;button.innerHTML='Enviar para correção <span>→</span>'}}
document.addEventListener("click",function(event){const importButton=event.target.closest("[data-import-theme],#importThemeButton");if(importButton){document.querySelector("#themeFiles").click();return}const themeButton=event.target.closest("[data-use-theme]");if(themeButton){useTheme(themeButton.dataset.useTheme);return}const nav=event.target.closest("[data-page]");if(nav){navigate(nav.dataset.page);return}const filter=event.target.closest("[data-filter]");if(filter){currentFilter=filter.dataset.filter;document.querySelectorAll(".filter").forEach(function(b){b.classList.toggle("active",b===filter)});renderEssays();return}const view=event.target.closest("[data-view]");if(view){currentView=view.dataset.view;document.querySelectorAll(".view-button").forEach(function(b){b.classList.toggle("selected",b===view)});renderEssays();return}const action=event.target.closest("[data-action]");if(action){const essay=allEssays().find(function(e){return String(e.id)===action.dataset.id});if(!essay)return;if(action.dataset.action==="open"){openResult(essay)}else if(action.dataset.action==="delete"){fetch("/api/essays/"+encodeURIComponent(essay.id),{method:"DELETE"}).then(refreshEssays);savedEssays=savedEssays.filter(function(e){return String(e.id)!==String(essay.id)});renderEssays();showToast("Redação removida.")}else if(action.dataset.action==="retry"){fetch("/api/essays/"+encodeURIComponent(essay.id)+"/retry",{method:"POST"}).then(async function(response){const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível reenviar.");savedEssays=savedEssays.map(function(item){return item.id===essay.id?data:item});renderEssays();showToast("Nova tentativa iniciada.");startPolling()}).catch(function(error){showToast(error.message)})}}});
