document.querySelector("#resultContent").addEventListener("click",function(event){const button=event.target.closest("[data-evidence-id]");if(!button)return;const mark=document.getElementById(button.dataset.evidenceId)||Array.from(document.querySelectorAll(".evidence-mark")).find(function(item){return (item.dataset.annotationIds||"").split(" ").includes(button.dataset.evidenceId)});if(mark){mark.scrollIntoView({behavior:"smooth",block:"center"});mark.classList.remove("evidence-pulse");void mark.offsetWidth;mark.classList.add("evidence-pulse")}});
const correctionPage=document.querySelector("#correctionPage"),fullscreenCorrectionButton=document.querySelector("#fullscreenCorrection");
function syncCorrectionFullscreen(){if(!correctionPage||!fullscreenCorrectionButton)return;const active=document.fullscreenElement===correctionPage||correctionPage.classList.contains("correction-page-focus");fullscreenCorrectionButton.textContent=active?"⤢ Sair da tela total":"⛶ Tela total";fullscreenCorrectionButton.setAttribute("aria-pressed",String(active));document.body.classList.toggle("correction-fullscreen-active",active)}
if(correctionPage&&fullscreenCorrectionButton)fullscreenCorrectionButton.addEventListener("click",async function(){if(document.fullscreenElement===correctionPage){await document.exitFullscreen();return}if(correctionPage.classList.contains("correction-page-focus")){correctionPage.classList.remove("correction-page-focus");syncCorrectionFullscreen();return}try{if(correctionPage.requestFullscreen)await correctionPage.requestFullscreen();else throw new Error("Fullscreen indisponível")}catch(error){correctionPage.classList.add("correction-page-focus");syncCorrectionFullscreen()}});
document.addEventListener("fullscreenchange",syncCorrectionFullscreen);
document.addEventListener("keydown",function(event){if(event.key==="Escape"&&correctionPage&&correctionPage.classList.contains("correction-page-focus")){correctionPage.classList.remove("correction-page-focus");syncCorrectionFullscreen()}});
renderEssays();renderThemes();renderDashboard();if(new URLSearchParams(location.search).get("page")==="repertoire")navigate("repertoire");refreshThemes();refreshEssays().then(function(){startPolling();if(location.hash.startsWith("#correcao/")){const id=decodeURIComponent(location.hash.slice(10));const essay=allEssays().find(function(e){return String(e.id)===id});if(essay&&essay.result)openResult(essay,true)}});
